def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    centers=[(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0,3)]
    for r,c,v in centers:
        for i in range(h):
            if out[i][c]==0: out[i][c]=v
    for r,c,v in centers:
        for j in range(w):
            if out[r][j]==0: out[r][j]=v
    return out
out=transform(grid)
print(out)

def transform2(g):
 h,w=len(g),len(g[0]); out=[row[:] for row in g]
 cs=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c] not in (0,3)]
 for r in range(h):
  for c in range(w):
   if g[r][c]!=0: continue
   cand=[]
   for a,b,v in cs:
    if r==a: cand.append((abs(c-b),1,v)) # horizontal tie lower priority
    if c==b: cand.append((abs(r-a),0,v))
   if cand: out[r][c]=min(cand)[2]
 return out
out=transform2(grid)
print(out)

